import java.io.*;
import java.util.*;

public class Main {
    static class DSU {
        int[] parent;
        int[] rank;

        DSU(int n) {
            parent = new int[n + 1];
            rank = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        boolean union(int a, int b) {
            int ra = find(a);
            int rb = find(b);
            if (ra == rb) return false;

            if (rank[ra] < rank[rb]) {
                int tmp = ra;
                ra = rb;
                rb = tmp;
            }

            parent[rb] = ra;
            if (rank[ra] == rank[rb]) {
                rank[ra]++;
            }
            return true;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        DSU dsu = new DSU(N);

        int[] roadU = new int[M];
        int[] roadV = new int[M];
        int roadCount = 0;

        boolean hydroCycle = false;

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());

            if (t == 1) {
                if (!dsu.union(a, b)) {
                    hydroCycle = true;
                }
            } else {
                roadU[roadCount] = a;
                roadV[roadCount] = b;
                roadCount++;
            }
        }

        if (hydroCycle) {
            System.out.println("N");
            return;
        }

        int keptRoads = 0;
        for (int i = 0; i < roadCount; i++) {
            if (dsu.union(roadU[i], roadV[i])) {
                keptRoads++;
            }
        }

        int removedRoads = roadCount - keptRoads;

        System.out.println(removedRoads <= K ? "S" : "N");
    }
}
