    static class DSU {
        int[] parent, size;

        DSU(int n) {
            parent = new int[n + 1];
            size = new int[n + 1];
            for (int i = 0; i <= n; i++) {
                parent[i] = i;
                size[i] = 1;
            }
        }

        int find(int x) {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        }

        boolean union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return false;
            if (size[a] < size[b]) {
                int tmp = a;
                a = b;
                b = tmp;
            }
            parent[b] = a;
            size[a] += size[b];
            return true;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());

        DSU water = new DSU(N);
        int[] roadU = new int[M];
        int[] roadV = new int[M];
        int roadCnt = 0;
        boolean waterCycle = false;

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            int t = Integer.parseInt(st.nextToken());

            if (t == 1) {
                if (!water.union(a, b)) {
                    waterCycle = true;
                }
            } else {
                roadU[roadCnt] = a;
                roadV[roadCnt] = b;
                roadCnt++;
            }
        }

        if (waterCycle) {
            System.out.println("N");
            return;
        }

        boolean[] seenWaterRoot = new boolean[N + 1];
        int[] waterRoots = new int[N];
        int C = 0;

        for (int v = 1; v <= N; v++) {
            int r = water.find(v);
            if (!seenWaterRoot[r]) {
                seenWaterRoot[r] = true;
                waterRoots[C++] = r;
            }
        }

        DSU comp = new DSU(N);

        for (int i = 0; i < roadCnt; i++) {
            int a = water.find(roadU[i]);
            int b = water.find(roadV[i]);
            if (a != b) {
                comp.union(a, b);
            }
        }

        boolean[] seenComp = new boolean[N + 1];
        int cc = 0;

        for (int i = 0; i < C; i++) {
            int r = comp.find(waterRoots[i]);
            if (!seenComp[r]) {
                seenComp[r] = true;
                cc++;
            }
        }

        int maxKeep = C - cc;
        int minDelete = roadCnt - maxKeep;

        System.out.println(minDelete <= K ? "S" : "N");
    }
